/* 1) 高亮所有窗户 (蓝色) */
const windows = ssp.objectsTool.getByUserDataProperty('renderType', 'WINDOW');
windows.forEach(o => ssp.objectsTool.setHighlight(o, '#29ccff'));

/* 2) 高亮所有门 (红色) + 所有厕所 (绿色) */
const doors = ssp.objectsTool.getByUserDataProperty('renderType', 'DOOR');
doors.forEach(o => ssp.objectsTool.setHighlight(o, '#ff0000'));
const toilets = ssp.objectsTool.getByUserDataProperty('spaceType', 'TOILET');
toilets.forEach(o => ssp.objectsTool.setHighlight(o, '#00ff00'));

/* 3) 只取消本次窗户高亮 */
windows.forEach(o => ssp.objectsTool.unHighlight(o));
